-- UCR clubs and student groups (HighlanderLink public directory, retrieved 2026-10-08).
-- Generated by supabase/scripts/build_clubs_migration.py.
--
-- Meeting times are free text exactly as each club reported them
-- (e.g. 'Tuesdays/Thursdays at 8pm', 'Varies with schedule'), so they are
-- stored as text, not structured times. Null = the club did not publish one.

create table public.clubs (
  id                integer primary key,      -- HighlanderLink organization ID
  name              text not null,
  organization_type text,                     -- Registered Student Organization, ...
  categories        text[],                   -- {'Academic/Professional','Service'}
  meeting_schedule  text,                     -- reported day/time, free text
  meeting_frequency text,                     -- Weekly, Every two weeks, Monthly, ...
  meeting_notes     text,                     -- meeting/practice lines from the description
  summary           text,
  description       text,
  email             text,
  website           text,
  instagram         text,
  profile_url       text
);

create index clubs_name_idx on public.clubs (name);

alter table public.clubs enable row level security;
create policy "Clubs are readable by everyone" on public.clubs for select using (true);

insert into public.clubs (id, name, organization_type, categories, meeting_schedule,
  meeting_frequency, meeting_notes, summary, description, email, website, instagram, profile_url) values
(420507, 'Free Enterprise, Entrepreneurship and Networking club', 'Registered Student Organization', array['Academic/Professional']::text[], 'From 5pm - 9pm', 'Weekly', null, 'Understand product-market fit and how to validate ideas. Learn the principles of user-centered design and prototyping Combine product, design, and strategy into a cohesive business concept.', 'FEEN (Future Entrepreneurs and Executives Network) is a student-led organization at the University of California, Riverside, dedicated to cultivating the next generation of innovative entrepreneurs, business leaders, and creative thinkers. The club provides hands-on experiences that bridge product development, design thinking, and business strategy through workshops, guest speakers, pitch sessions, and collaborative projects. FEEN’s goal is to empower students to think critically, act creatively, and build inclusively while learning how to understand product-market fit, user-centered design, and strategic business planning. Rooted in the belief of being “men and women for and with others,” FEEN strives to prepare its members to turn ideas into impactful ventures that drive growth, innovation, and positive change.', 'feenucr@gmail.com', null, 'https://www.instagram.com/feenucr', 'https://highlanderlink.ucr.edu/organization/feen'),
(71070, '909 Dance Troupe', 'Registered Student Organization', array['Recreational']::text[], 'Tuesdays/Thursdays at 8pm', 'Weekly', null, 'To better the awareness and development of hip-hop dance through educational and social means, with the cooperation of administration, faculty and students. Strength in our roots. Power in our number: 909.', 'We, the members of 909 Dance Troupe (formally known as 909 Hip Hop Dance Troupe), at the University of California, Riverside, in conjunction with Hip Hop’s core principles, strive to honor Hip Hop’s roots in Black culture and to further the development of dance through both educational and social means, with the cooperation of administration, faculty and students.
In 1997, the seeds of Hip-Hop were planted at the University of California, Riverside forming 909 Dance Troupe. Representing Riverside, CA, 909 opens its membership to all dancers in the community. For 30 years, 909 has created an image that is recognized and respected for its connection to underground hip-hop music. Although the team has evolved throughout the years, 909 respects its roots in underground hip-hop and continues its expression to the masses through originality, unique styles of music, and the art of dance. “Strength in our roots, power in our number: 909.”', '909managers@gmail.com', null, 'https://www.instagram.com/909dt/', 'https://highlanderlink.ucr.edu/organization/909'),
(222299, 'A Friend in Me', 'Registered Student Organization', array['Service']::text[], 'We meet bimonthly on Mondays at 6 pm. Socials or other events may be held during other days of the week. Please sign up for our mailing list, follow our Instagram, or text @afimucr to 81010 to receive more information regarding events.', 'Every two weeks', 'A Friend in Me is an organization dedicated to providing pediatric cancer patients with a sense of normalcy and friendship. This club provides members with hospital volunteering, networking, and patient-interaction opportunities, fostering professional growth.
We meet several times a quarter with snacks, icebreakers, and more! Join us on HighlanderLink to receive updates about our meeting times and locations or email one of our officers (listed below) to learn more about our club! You can also text @afimucr to 81010 receive text updates.', 'A Friend in Me is an organization dedicated to providing pediatric cancer patients with a sense of normalcy and friendship. This club provides members with volunteering, networking, and patient-interaction opportunities, fostering professional growth.', 'Welcome to our club! We''re so happy you''re here!
A Friend in Me is an organization dedicated to providing pediatric cancer patients with a sense of normalcy and friendship. This club provides members with hospital volunteering, networking, and patient-interaction opportunities, fostering professional growth.
We meet several times a quarter with snacks, icebreakers, and more! Join us on HighlanderLink to receive updates about our meeting times and locations or email one of our officers (listed below) to learn more about our club! You can also text @afimucr to 81010 receive text updates.', 'afriendinmeclubucr@gmail.com', null, 'https://www.instagram.com/afriendinmeucr/', 'https://highlanderlink.ucr.edu/organization/afriendinme'),
(118609, 'A. Gary Anderson Graduate School of Management Student Association', 'Graduate Student Association', array['Mini-GSA']::text[], 'Monday 5-6PM', 'Monthly', null, 'The AGSM student association aims to enhance the graduate experience and lay a foundation for growth by supporting a network of students, faculty, staff, alumni and the UCR community.', 'AGSMSA strives to enhance the value of the A. Gary Anderson Graduate School of Management experience by creating student-centered programs, services, and involvement opportunities which celebrate diversity, advertise the UCR AGSM branding, promote alumni retention, foster leadership, civic engagement, and student development. We develop and enhance communication and interaction between students, faculty, administrators, alumni, business leaders, and our broader network of contacts.', 'agsmsaucr@gmail.com', 'http://agsm.ucr.edu/services_resources/student_ass', null, 'https://highlanderlink.ucr.edu/organization/agsmsa'),
(319601, 'Aag: Fusion Dance Team', 'Registered Student Organization', array['Recreational']::text[], 'Monday, Wednesday, Thursday, Sunday', 'Weekly', null, 'Aag is the Competitive Premier Fusion Bollywood Dance team. Aag is referred to as “fire” and we hope to show that passion on stage. We’re looking to establish our team by showing excellence in styles such as Bollywood, Hip Hop, and Bhangra.', 'Aag at UCR, is Riverside''s Premier Bollywood Fusion Team! We specialize in various styles such as hip-hop, contemporary, jazz, bollywood, etc! We want to share our love and passion for dance with the community and allow for our dancers to flourish in a supportive environment.', 'ucraag@gmail.com', 'https://aag.ucrhighlanders.org/', 'https://www.instagram.com/ucraag/?igshid=MzRlODBiNWFlZA%3D%3D', 'https://highlanderlink.ucr.edu/organization/aag'),
(230819, 'Abhinaya', 'Registered Student Organization', array['Arts and Expression']::text[], 'Twice a week for 2 hours each, typically in the evening between 6-10!', 'Weekly', null, 'Abhinaya is the premier competitive and local Indian Classical dance team at the University of California, Riverside established in 2018. This year Abhinaya enters the 3rd Generation of competition season.', 'Abhinaya is the premier competitive and local Indian Classical dance team at the University of California, Riverside. The competition team combines various types of dance styles including Bharatanatyam and Kathak to create pieces that tell an intricate and beautiful story. The local team combines all 8 classical dance styles of India to showcase their culture at UCR and in all of SoCal. Their purpose is to help classical dancers keep their passion alive throughout college.
Hi potential member!
We are so excited to have you here! Abhinaya is recruiting in the fall but we hold various events throughout the year, so feel free to join us whenever you can. Our main recruitment will be during the Fall and we will keep you most updated on our Instagram page: @abhinaya.ucr We also have a local team that auditions ever quarter and we love participating in competitions and cultural events during the year.
Follow us, send us a message, and we hope to see you at one of our auditions or workshops!', 'ucrabhinaya@gmail.com', null, 'http://instagram.com/abhinaya.ucr', 'https://highlanderlink.ucr.edu/organization/abhinaya'),
(431482, 'ABLE', 'Registered Student Organization', array['Academic/Professional']::text[], 'Monday, 7:30PM', 'Weekly', null, 'We bring Christian business students and professionals together to grow in faith, leadership, and excellence. Through mentorship, fellowship, and real-world learning, we live out the Gospel in business.', 'We bring Christian business students and professionals together to grow in faith, leadership, and excellence. Through mentorship, fellowship, and real-world learning, we live out the Gospel in business.', null, null, null, 'https://highlanderlink.ucr.edu/organization/ableucr'),
(71049, 'Accounting Society at UC Riverside', 'Registered Student Organization', array['Academic/Professional']::text[], 'Tuesdays or Thursdays at 7 PM', 'Weekly', null, 'The Accounting Society aims to promote the educational and professional experience of accounting students at UCR by giving members exposure to internship/full-time opportunities to work with accounting firms and government agencies.', 'The Accounting Society aims to educate and enhance the professional experience of accounting students at UCR by giving members exposure to internship/full-time opportunities to work with accounting firms and government agencies.
Follow us on Instagram:https://www.instagram.com/ucraccountingsociety/?hl=en', 'asucr54@gmail.com', 'http://www.asucr.org', 'https://www.instagram.com/ucraccountingsociety/?hl=en', 'https://highlanderlink.ucr.edu/organization/ucraccountingsociety'),
(425117, 'Ace of Cultures', 'Registered Student Organization', array['Recreational']::text[], null, 'Monthly', null, 'Ace of Cultures builds an inclusive UCR community by connecting students through games from cultures worldwide. Through cultural game nights, tournaments, food, and music, AOC promotes connection, learning, and cultural appreciation.', 'The purpose of Ace of Cultures is to foster an inclusive and welcoming community at the University of California, Riverside by bringing students together through games from diverse cultures around the world. The organization aims to help students feel connected to their own cultural backgrounds while also learning about and appreciating the cultures of others through interactive, strategy-based, and social games.
Ace of Cultures hosts cultural game nights, tournaments, and social events featuring games specific to different regions and traditions, such as card games, board games, and team-based strategy games. Through shared experiences involving gameplay, food, and music, AOC seeks to promote cultural understanding, community-building, and meaningful social connections among students of all backgrounds.', 'Mkhad006@ucr.edu', null, null, 'https://highlanderlink.ucr.edu/organization/aceofcultures'),
(82095, 'Active Minds', 'Department Affiliated Organization', array['Department Affiliated Organization']::text[], null, 'Every two weeks', null, 'Reduce the stigma that often surrounds mental health issues on college campuses by increasing awareness, coordinating interactive events, and providing mental health and wellness resources and support.', 'Active Minds
Active Minds is a UCR student-lead group committed to helping you feel your best and removing the stigma surrounding mental health. We provide guest speakers, information tables and outreach programs to help you manage stress and find help when needed. You''ll get real answers from peer mentors you can relate to, feel safe and connected, while living well and taking part in fun and rewarding activities.
If you are interested in volunteering with us, our applications will be available during Week 8. Applications are open quarterly. If you have any questions, please email us at activeminds@ucr.edu.', 'activeminds@ucr.edu', 'http://activeminds.org', 'https://www.instagram.com/activemindsucr/?hl=en', 'https://highlanderlink.ucr.edu/organization/activeminds'),
(367110, 'Adventure Club', 'Registered Student Organization', array['Recreational']::text[], null, 'Every two weeks', null, 'Adventure Club at UCR is a new hiking organization committed to fostering an inclusive community of diverse explorers. Together, we embark on expeditions that not only connect students but also celebrate the breathtaking beauty of Southern California.', 'Adventure Club at UCR is a new hiking organization committed to fostering an inclusive community of diverse explorers. Together, we embark on expeditions that not only connect students but also celebrate the breathtaking beauty of Southern California.
Check Out Our Linktree
Check Out Our Instagram (@ucradventureclub)', 'ucradventureclub@gmail.com', 'https://linktr.ee/ucradventureclub', 'https://www.instagram.com/ucradventureclub/', 'https://highlanderlink.ucr.edu/organization/ac'),
(70921, 'Afghan Student Association', 'Registered Student Organization', array['Cultural']::text[], 'Thursdays @ 7pm', 'Every two weeks', null, 'The Afghan Student Association seeks to act as a resource for Afghan students and their peers to come together in an effort to learn more about Afghan history and culture.', 'The Afghan Student Association is a student organization at UCR that is dedicated to raising awareness and understanding of the Afghan culture. It is open to every UCR student interested in learning more about Afghanistan. This organization prioritizes the effort to bring together its members and the student body through fundraisers, cultural shows, activities, and social events at and around the University of California, Riverside. Reach out to us via our IG (@ucrasa).', null, null, 'http://www.instagram.com/ucrasa/', 'https://highlanderlink.ucr.edu/organization/asa'),
(70919, 'African Americans United in Science (AAUS)', 'Registered Student Organization', array['Academic/Professional']::text[], 'Thursday 6-7pm', 'Every two weeks', null, 'The purpose of AAUS is to increase the educational and professional opportunities available to African American science students at the University of California, Riverside; stimulate the dissemination of valuable information to these students', 'The purpose of AAUS is to increase the educational and professional opportunities available to African American science students at the University of California, Riverside; stimulate the dissemination of valuable information to both student and the overall community, and provide social, cultural, and volunteer activities that serve to enrich the undergraduate experience of AAUS members.
To familiarize AAUS members with graduate and professional school information and career opportunities in the sciences.
To unite African American students in the sciences, and provide academic and professional support, in order to create a network of connections and resources
accessible to students.
To obtain and disperse information for and encourage participation in) professional mentoring, summer programs, research opportunities, and conferences pertinent to the success of AAUS members in their particular fields of study.
To educate AAUS members about the history of African Americans in science, and encourage them to strive towards success in the future.', 'aaus.at.ucr@gmail.com', null, 'https://www.instagram.com/aaus_ucr/', 'https://highlanderlink.ucr.edu/organization/aaus'),
(377063, 'Ahlul-Bayt Student Association', 'Registered Student Organization', array['Spiritual/Religious/Atheist']::text[], 'Thursdays at 5:00PM', 'Twice a quarter', 'ABSA is a religious organization that caters to the spiritual and educational needs of Muslim students, with all aspects aligning with the teachings of the Qur’an and sunnah of the Prophet Muhammad (SAW) and his Ahlul-Bayt (AS). Although we mainly cater to the needs of Shia Muslim students on campus, we are dedicated to providing a safe space and environment welcoming all backgrounds to our events and meetings.', 'ABSA is a religious organization that caters to the spiritual and educational needs of Muslim students, with all aspects aligning with the teachings of the Qur’an and sunnah of the Prophet Muhammad (SAW) and his Ahlul-Bayt (AS).', 'ABSA is a religious organization that caters to the spiritual and educational needs of Muslim students, with all aspects aligning with the teachings of the Qur’an and sunnah of the Prophet Muhammad (SAW) and his Ahlul-Bayt (AS). Although we mainly cater to the needs of Shia Muslim students on campus, we are dedicated to providing a safe space and environment welcoming all backgrounds to our events and meetings.', 'absaucr@gmail.com', null, 'https://www.instagram.com/absaucr/', 'https://highlanderlink.ucr.edu/organization/absaucr'),
(405223, 'Alight Campus Ministry at UCR', 'Registered Student Organization', array['Spiritual/Religious/Atheist']::text[], 'Monday at 7:00PM', 'Weekly', 'Settle in and find rest in Christ, alight in His presence with us! We host weekly bible studies and other exciting activities to help us grow together as we follow Jesus. Founded on Acts 2:38 and John 8:12.', 'Settle in and find rest in Christ, alight in His presence with us! We host weekly bible studies and other exciting activities to help us grow together as we follow Jesus. Founded on Acts 2:38 and John 8:12.', 'Settle in and find rest in Christ, alight in His presence with us! We host weekly bible studies and other exciting activities to help us grow together as we follow Jesus. Founded on Acts 2:38 and John 8:12.', 'campusministryatucr@gmail.com', null, 'https://www.instagram.com/alightatucr?utm_source=ig_web_button_share_sheet&igsh=ZDNlZDc0MzIxNw==', 'https://highlanderlink.ucr.edu/organization/alightatucr'),
(71079, 'Alpha Chi Omega', 'Fraternities and Sororities', array['Fraternity/Sorority']::text[], 'Monday 7:00PM', 'Weekly', 'Every year, Iota Xi chapter celebrates Healthy Relationships Week during the week of Valentine''s Day. This year it was on February 11-17, 2025, where we took part in a nationwide recognition to promote healthy relationships, and by doing so, help prevent domestic violence and sexual assault. We held workshops about what a healthy relationship should look like and how respect is a two-way street. Also, our Vice President of Public Relations introduced a social media challenge in which everyone was able to participate, encouraging members to promote healthy relationships with photos on Instagram.
During the Summer, we prepared for fall recruitment. We have a pre-recruitment week where we are able to practice and prepare for recruitment as well as hold many bonding activities!
We are fortunate that Fall Recruitment is during the month of October, as it is just one of the many reasons to recognize Domestic Violence Awareness Month! We hold weekly events and every member works to empower and impact others through our philanthropy. We cannot wait to share our values, philanthropy, and sisterhood with so many amazing women and welcome in a new member class! We prepare for recruitment year round, and we hope the recruitment process is as empowering for potential new members as it is for us!', 'Alpha Chi Omega is a national women''s organization that enriches the lives of members through lifetime opportunities for friendship, leadership, learning, and service.', 'Alpha Chi Omega is a national women''s organization that enriches the lives of members through lifetime opportunities for friendship, leadership, learning, and service.
Alpha Chi Omega''s national philanthropy supports Survivors of Domestic Violence and promotes domestic violence awareness. To support our cause, Iota Xi held our annual Next Top Alpha in the Spring of 2025. In this pageant-like event, our campus'' fraternities, sororities and other greek organizations raised money through fundraisers in the weeks leading up to the event and our sisters, friends and family all donated as well. Organizations on campus and people of all ages are invited to our community wide event to contribute to the cause and buy tickets to watch their peers compete for Next Top Alpha. Together, this philanthropic event worked to fight domestic violence by raising awareness and money for the Riverside Area Rape Crisis Center. As an Organization we have raised over $100,000 for NORA.
This past Winter, Iota Xi sent the Chapter President, Vice President of Chapter Relations & Standards, Vice President of Risk Management, and our Vice President of Membership Programming to a Leadership Academy in Indianapolis, Indiana where they advanced their skills as leaders and got the opportunity to make connections with sisters from chapters across the nation! We are recognized for focusing on diversity, equity, boosting member moral, and mental health programming. We encourage diversity and inclusion for all of our members!
Every year, Iota Xi chapter celebrates Healthy Relationships Week during the week of Valentine''s Day. This year it was on February 11-17, 2025, where we took part in a nationwide recognition to promote healthy relationships, and by doing so, help prevent domestic violence and sexual assault. We held workshops about what a healthy relationship should look like and how respect is a two-way street. Also, our Vice President of Public Relations introduced a social media challenge in which everyone was able to participate, encouraging members to promote healthy relationships with photos on Instagram.
During the Summer, we prepared for fall recruitment. We have a pre-recruitment week where we are able to practice and prepare for recruitment as well as hold many bonding activities!
We are fortunate that Fall Recruitment is during the month of October, as it is just one of the many reasons to recognize Domestic Violence Awareness Month! We hold weekly events and every member works to empower and impact others through our philanthropy. We cannot wait to share our values, philanthropy, and sisterhood with so many amazing women and welcome in a new member class! We prepare for recruitment year round, and we hope the recruitment process is as empowering for potential new members as it is for us!', 'axo.ucr.president@gmail.com', 'http://www.mychapterroom.com/axo-iotaxi/external/index.asp', 'https://www.instagram.com/axo_ucr/?hl=en', 'https://highlanderlink.ucr.edu/organization/achio'),
(122604, 'Alpha Delta Pi', 'Fraternities and Sororities', array['Fraternity/Sorority']::text[], 'Mondays at 8:00PM', 'Weekly', null, 'Established in 1851, Alpha Delta Pi is committed to sisterhood, values and ethics, high academic standards and social responsibility. Our open motto, We Live for Each Other, is something that our sisters live by every day.', 'Established in 1851, Alpha Delta Pi is committed to sisterhood, values and ethics, high academic standards and social responsibility. Our open motto, We Live for Each Other, is something that our sisters live by every day.', 'adpi.thetaomega.president@gmail.com', 'http://ucr.alphadeltapi.org/', 'https://www.instagram.com/ucradpi/?hl=en', 'https://highlanderlink.ucr.edu/organization/alphadeltapi'),
(71064, 'Alpha Epsilon Pi Fraternity', 'Fraternities and Sororities', array['Fraternity/Sorority']::text[], '7 p.m. Sundays', 'Weekly', null, 'Alpha Epsilon Pi was founded to provide opportunities for the Jewish college man seeking the best possible college and fraternity experience.', 'Alpha Epsilon Pi was founded to provide opportunities for the Jewish college man seeking the best possible college and fraternity experience.', 'aepiriverside@gmail.com', 'http://aepixp.org/', 'https://www.instagram.com/aepi_ucr/', 'https://highlanderlink.ucr.edu/organization/aepi'),
(71165, 'Alpha Gamma Alpha Sorority', 'Fraternities and Sororities', array['Fraternity/Sorority']::text[], null, 'Weekly', null, 'To unify students to work towards the advancement of Armenian casuses, our college community, and the greater community.', 'To unify students to work towards the advancement of Armenian casuses, our college community, and the greater community. Alpha Gamma Alpha is a multi-cultural sorority that strives to unify women of all cultures while supporting the Armenian culture and causes. Alpha Gamma Alpha is dedicated to fostering the interests of ambitious women, with Alumni going on to pursue careers in the fields of law, medicine, psychology and business.', 'agadeltachapter@gmail.com', 'https://www.alphagammaalpha.org/about', 'http://www.instagram.com/ucr_aga/', 'https://highlanderlink.ucr.edu/organization/alphagammaalphasorority'),
(71036, 'Alpha Kappa Alpha Sorority Inc. (Kappa Theta Chapter)', 'Fraternities and Sororities', array['Fraternity/Sorority']::text[], null, null, null, 'Service to All ManKind', null, null, 'http://aka1908.com', 'https://www.instagram.com/akakappatheta/', 'https://highlanderlink.ucr.edu/organization/aka'),
(71083, 'Alpha Kappa Psi', 'Registered Student Organization', array['Academic/Professional']::text[], 'Wednesdays at 8:00 PM', 'Weekly', null, 'Developing well-trained, ethical, skilled, resourceful, experienced business leaders.', 'In 1904, Alpha Kappa Psi was founded on the principles of educating its members and the public to appreciate and demand higher ideals in business and to further the individual welfare of members during college and beyond.
College men and women everywhere are discovering that Alpha Kappa Psi is much more than just another organization or club—it is a unique, prestigious association of students, professors, graduates and professionals with common interests and goals. They join Alpha Kappa Psi to take advantage of valuable educational, friendship and networking opportunities.', 'ucrakpsi@gmail.com', 'https://www.akpsiriverside.org/', 'https://www.instagram.com/ucrakpsi/?hl=en', 'https://highlanderlink.ucr.edu/organization/akpsi'),
(70964, 'Alpha Phi Omega', 'Registered Student Organization', array['Service']::text[], 'Thursdays, 8 PM', 'Weekly', null, 'Alpha Phi Omega is a national coeducational service organization founded on the principles of Leadership, Friendship, and Service. It provides its members the opportunity to develop leadership skills as they volunteer in various areas.', 'Alpha Phi Omega is a national coeducational service organization founded on the principles of Leadership, Friendship and Service. It provides its members the opportunity to develop leadership skills as they volunteer on their campus, in their community, to the nation, and to the organization. With more than 400,000 members on over 375 campuses, Alpha Phi Omega continues to provide more service on more campuses than any other collegiate service organization.
It is the VISION of Alpha Phi Omega to be recognized as the premier service-based leadership development organization.
It is the MISSION of Alpha Phi Omega to prepare campus and community leaders through service.
The VALUES of Alpha Phi Omega are to develop leadership, promote friendship and provide service.
The OBJECTIVES of Alpha Phi Omega are Share, Grow, Improve and Invest.', 'apo.presidentucr@gmail.com', 'https://apoprit.wixsite.com/alpha-phi-omega-ucr?utm_source=ig&utm_medium=social&utm_content=link_in_bio', 'https://www.instagram.com/apoucr/', 'https://highlanderlink.ucr.edu/organization/aphio'),
(70962, 'Alpha Pi Sigma Sorority, Incorporated.', 'Fraternities and Sororities', array['Fraternity/Sorority']::text[], 'Mondays at 8PM', 'Weekly', null, 'Alpha Pi Sigma Sorority, Incorporated sisters strive academically, personally, and professionally in a commitment to excellence and with a desire to support one another.', 'Alpha Pi Sigma Sorority, Incorporated was established at the University of California, Riverside on March 5, 2000. A group of Latina women from a variety of backgrounds came together to form an organization that would unite and support women on university campuses. Our sisterhood is composed of educated, professional, diverse women committed to the empowerment of women and the Latin American community. We achieve these accomplishments through academic enrichment programs, community service, leadership development opportunities, and other activities geared towards the appreciation, promotion, and preservation of our surrounding communities. If you are interested in joining please reach out to us on Instagram or by email!', 'delta_rep@alphapisigma.org', 'https://www.alphapisigma.org/', 'https://www.instagram.com/ucralphapisigma/', 'https://highlanderlink.ucr.edu/organization/aps'),
(425236, 'Alternative Investments Group', 'Registered Student Organization', array['Academic/Professional']::text[], null, 'Weekly', null, 'We educate students in asset management across public and private markets while developing skills in financial modeling, valuation, portfolio construction, and research. Members engage in real-world simulations and connect with industry professionals.', null, null, null, null, 'https://highlanderlink.ucr.edu/organization/altinvestments'),
(406678, 'Alzheimers Foundation of America at UCR', 'Registered Student Organization', array['Action & Awareness']::text[], 'Wednesday @ 6PM', 'Bi-weekly', null, 'To raise awareness, provide education, and foster a supportive community for those affected by Alzheimer''s disease as well as inspire individuals to learn about Alzheimer’s disease through advocacy, volunteer efforts, and scientific discussions.', 'To raise awareness, provide education, and foster a supportive community for those affected by Alzheimer''s disease as well as inspire individuals to learn about Alzheimer’s disease. Through advocacy, volunteer efforts, and scientific discussions, we aim to promote understanding, contribute to research efforts, and support individuals and families impacted by neurodegenerative conditions', 'afaatucr@gmail.com', null, 'https://www.instagram.com/afaatucr/', 'https://highlanderlink.ucr.edu/organization/afaatucr'),
(70827, 'American Association for Aerosol Research Student Chapter at UCR', 'Graduate Student Association', array['Graduate Student Organization']::text[], null, 'Monthly', null, 'AAAR Student Chapter fosters a community for which students can exchange scientific ideas about aerosol research.', 'The purpose of this organization shall be to provide opportunity for students and professionals in or out of UCR to exchange scientific ideas about aerosol and atmosphere research.', 'ebowe010@ucr.edu', null, null, 'https://highlanderlink.ucr.edu/organization/aaarstudentchapteratucr'),
(424543, 'American Cancer Society at UCR', 'Registered Student Organization', array['Action & Awareness']::text[], 'Tuesday, 5:00pm', 'Monthly', null, 'Our organization fulfills its mission by spreading awareness about cancer and engaging the UCR community through service, fundraising, and educational events aligned with ACS’s three pillars of advocacy, discovery, and patient support.', null, 'ucramericancancersociety@gmail.com', null, 'https://www.instagram.com/ucracs/', 'https://highlanderlink.ucr.edu/organization/ucracs'),
(71091, 'American Institute of Chemical Engineers (AIChE)', 'Registered Student Organization', array['Academic/Professional']::text[], 'Follow us on Instagram @aicheucr or Discord https://discord.gg/fbqCt22Tqt for updates!', 'Every two weeks', 'AIChE is a professional affiliation consisting of Chemical and Environmental Engineers. AIChE at UCR provides opportunities for all students to tour facilities, meet professionals in industry, and advance academically and professionally through a series of workshops.', 'AIChE is a professional affiliation consisting of Chemical and Environmental Engineers, but all majors are welcome to join!', 'AIChE is a professional affiliation consisting of Chemical and Environmental Engineers. AIChE at UCR provides opportunities for all students to tour facilities, meet professionals in industry, and advance academically and professionally through a series of workshops.', 'aiche.ucr@gmail.com', 'https://sites.google.com/ucr.edu/aicheatucr', 'https://www.instagram.com/aicheucr/', 'https://highlanderlink.ucr.edu/organization/aicheucr'),
(71052, 'American Marketing Association at UCR', 'Registered Student Organization', array['Academic/Professional']::text[], 'Wednesday 5:00 - 6:00', 'Weekly', 'American Marketing Association (AMA) at UCR is a professional student organization that connects like minded individuals, cultivates individual growth, and provides programs to students who want to expand their knowledge in the field of business & marketing.
By providing weekly marketing workshops, guest speaker events, and networking socials, we help students become well-informed in the extensive field of marketing and how to apply these lessons in the real world. We are here as a resource for all students to inquire about the many ways marketing can be beneficial to one''s career, no matter what field they plan on heading toward.', 'A business student run organization focused on developing students into successful leaders in the field of marketing, management, advertising, public relations, sales, and other related fields. We participate in professional events, workshops, and others', 'American Marketing Association (AMA) at UCR is a professional student organization that connects like minded individuals, cultivates individual growth, and provides programs to students who want to expand their knowledge in the field of business & marketing.
By providing weekly marketing workshops, guest speaker events, and networking socials, we help students become well-informed in the extensive field of marketing and how to apply these lessons in the real world. We are here as a resource for all students to inquire about the many ways marketing can be beneficial to one''s career, no matter what field they plan on heading toward.', 'amaucr@gmail.com', 'https://amaucr.wixsite.com/website', 'https://www.instagram.com/amaucr/?hl=en', 'https://highlanderlink.ucr.edu/organization/ama'),
(71050, 'American Medical Student Association', 'Registered Student Organization', array['Academic/Professional']::text[], 'Even week Wednesdays, 6-7pm (e.g. Week 2 at 6-7 pm, Week 4 at 6-7 pm, etc.)', 'Every two weeks', 'What is AMSA you ask?
The American Medical Student Association (AMSA) is the largest Pre-Medical student organization in the nation, and is completely student governed, to best meet the needs of its audience as well as the largest pre-med/pre-health club on campus. As a nationwide medical on-campus organization, we host events that provide resources, knowledge and leadership opportunities in a vast array of committees that supports your aspiration to go into medical school. Pretty cool, right?
Wait, there is more!
AMSA is made up of a diverse group of students all running and working together through their own committees and interests, with a common shared goal: to help our fellow and neighboring students have the best chance at getting into the medical school of their choice and also shed light to another pre-health pathways through guest speakers, hands-on events, and more! This allows AMSA members to meet new and awesome colleagues and provide a support system throughout their years here at the University of California, Riverside.
With that said, Welcome aboard, AMSA!
For more information visit our website and sign-up for the mailing list at the URL below and follow us on Instagram @amsaucr!
https://www.amsaucr.org', 'To provide an environment that supports the creative ideas of physicians-in-training, knowledge and resources that guides students who are interested in the medical field.', 'Hello there! Are you interested in pre-medicine or pre-health? What, you are? Well then, AMSA is definitely the organization for you!
What is AMSA you ask?
The American Medical Student Association (AMSA) is the largest Pre-Medical student organization in the nation, and is completely student governed, to best meet the needs of its audience as well as the largest pre-med/pre-health club on campus. As a nationwide medical on-campus organization, we host events that provide resources, knowledge and leadership opportunities in a vast array of committees that supports your aspiration to go into medical school. Pretty cool, right?
Wait, there is more!
AMSA is made up of a diverse group of students all running and working together through their own committees and interests, with a common shared goal: to help our fellow and neighboring students have the best chance at getting into the medical school of their choice and also shed light to another pre-health pathways through guest speakers, hands-on events, and more! This allows AMSA members to meet new and awesome colleagues and provide a support system throughout their years here at the University of California, Riverside.
With that said, Welcome aboard, AMSA!
For more information visit our website and sign-up for the mailing list at the URL below and follow us on Instagram @amsaucr!
https://www.amsaucr.org', 'ucr.amsa@gmail.com', 'https://www.amsaucr.org', 'https://www.instagram.com/amsaucr/?hl=en', 'https://highlanderlink.ucr.edu/organization/amsa'),
(119156, 'American Medical Women''s Association', 'Registered Student Organization', array['Academic/Professional']::text[], 'Mondays, 6-7 pm', 'Every two weeks', null, 'To bring together those in Medicine and Health-related fields to promote Women’s Health and to support members’ professional and personal development.', 'The American Medical Women’s Association (AMWA) is an organization of women physicians, medical students, undergraduate students, and other individuals dedicated to serving as the unique voice for women’s health and the advancement of women in medicine. The organization was founded by Dr. Bertha VanHoosen in 1915 in Chicago, at a time when women physicians were an under-represented minority. To redress the decline in the percentage of women in senior leadership positions, AMWA has carried out ambitious advocacy efforts including research, constituency building, mentoring, leadership development, and policy reform to enable environmental and institutional transformation.
AMWA functions at the local, national, & international level to advance women in medicine & improve women’s health by providing & developing leadership, advocacy, education, expertise, mentoring, & strategic alliances. As a pre-med branch of the nationally established American Medical Women’s Association at UCR, our purpose is to bring together those in medicine and health-related fields on campus to promote women’s health and to support members’ professional and personal development. We also provide two mentorship programs, a MD one with the AMWA UCR School of Medicine, and a DO one with the Western University of Health Sciences, College of Osteopathic Medicine, to allow our members to form connections with current medical students. We hope to provide all our members with philanthropic opportunities and events to help them become active members of the community and go on to serve as our future physicians.
To join us, become a member here on Highlander Link! Stay updated on what''s going on by following us on Instagram: https://www.instagram.com/amwa_ucr/! Be sure to join our GroupMe as well: https://groupme.com/join_group/63566563/qn7eejFB!
https://www.youtube.com/watch?v=Eu-XmhSg1rw', 'amwaatucr@gmail.com', 'http://www.amwa-doc.org', 'https://www.instagram.com/amwa_ucr/?utm_source=ig_web_button_share_sheet&igshid=OGQ5ZDc2ODk2ZA==', 'https://highlanderlink.ucr.edu/organization/amwa'),
(70822, 'American Society of Mechanical Engineers at UCR (ASME)', 'Registered Student Organization', array['Academic/Professional']::text[], 'Varies by quarter. Times will be posted on Instagram and Discord.', 'Weekly', 'ASME seeks to develop well-rounded engineers at UC Riverside that are experienced and ready for the real world. We are an organization that robots (among other things) out of a love for engineering and because we understand the need for competent engineers worldwide. Through the various projects we are involved in, we can gain invaluable engineering experience before moving into the workforce. They say, "It''s not about what you know, but who you know." We have a growing network of talented students/engineers. Through our professional development, outreach, volunteering events, and workshops, this is your chance to meet experienced engineers, and other students, and to learn marketable skills.', 'To help engineering students develop professionally, socially and academically through: participating yearly in Regional ASME competitions, coordinating events with other ASME student chapters, and sponsoring industry-recruiting events.', 'ASME seeks to develop well-rounded engineers at UC Riverside that are experienced and ready for the real world. We are an organization that robots (among other things) out of a love for engineering and because we understand the need for competent engineers worldwide. Through the various projects we are involved in, we can gain invaluable engineering experience before moving into the workforce. They say, "It''s not about what you know, but who you know." We have a growing network of talented students/engineers. Through our professional development, outreach, volunteering events, and workshops, this is your chance to meet experienced engineers, and other students, and to learn marketable skills.', 'asme@ucr.edu', null, 'https://www.instagram.com/ucr.asme/', 'https://highlanderlink.ucr.edu/organization/asme'),
(419376, 'Anderson Fintech Club', 'Graduate Student Association', array['Graduate Student Organization']::text[], 'Every month''s second Wednesday afternoon at 2pm', 'Monthly', null, 'Empowering UCR students to navigate the future of finance &amp; tech. We connect members with industry leaders to foster responsible innovation, integrity, and accessible banking.', 'The Anderson Fintech Club is a student organization at the University of California, Riverside (UCR) dedicated to preparing students for the dynamic intersection of finance, technology, and compliance.
Our mission is to bridge the gap between students and the fintech industry by connecting them with regulators, founders, and financial institutions. We are committed to promoting responsible innovation in digital finance, upholding integrity and respect for regulatory institutions, and advocating for a just and accessible banking experience for all.
The club is open to all UCR students, staff, and faculty. We equip our members through a variety of events, including guest lectures, professional workshops, networking sessions, and case competitions. Our activities are led by an executive board of elected student officers and supported by a dedicated faculty co-founder.', 'andersonfintechclub@gmail.com', null, 'https://www.instagram.com/andersonfintechclub/', 'https://highlanderlink.ucr.edu/organization/fintechclub'),
(418804, 'Anime Diva Club', 'Registered Student Organization', array['Arts and Expression']::text[], 'Fridays', 'Weekly', null, 'This club centers women and femme-presenting anime fans to connect, create, and celebrate our love for anime without judgment. Most anime spaces feel male-dominated, so we figured, why not make our own space where we can just nerd out, hype each other up', null, 'animedivaclub@gmail.com', null, 'https://www.instagram.com/animedivaclub/', 'https://highlanderlink.ucr.edu/organization/anime-diva-club'),
(379460, 'Anti Warfare Warfare Club', 'Registered Student Organization', array['Recreational']::text[], 'Monday & Thursday 5 - 8 PM', 'Weekly', null, 'The Anti Warfare Warfare Club seeks to conduct analytical and educational wargaming to study conflict, tactics, international relations, military doctrine, and any other subject that connects to warfare.', 'We aim to study warfare and chase the many rabbit-hole connections to psychology, sociology, economics, political science, and more. We believe in a simple truth. You cannot prevent war, if you do not know how it works.
Our organization helps its members create tabletop exercises that reflect the reality of warfare in order to study the strategy, tactics, and decision-making that happens in command posts, situation rooms, and battlefields across space and time
Join us and let''s explore one of the most complex, fascinating, and sobering parts of human nature.
To stay updated on future events, please join the official club Discord and follow AWWC on Instagram: https://linktr.ee/awwcucr', 'antiwarfarewarfareclub@gmail.com', 'https://sites.google.com/view/awwcucr/home', 'http://www.instagram.com/awwcucr', 'https://highlanderlink.ucr.edu/organization/awwcucr'),
(420511, 'Aprendiendo Juntos', 'Registered Student Organization', array['Academic/Professional']::text[], 'Wednesdays and Thursdays', 'Weekly', null, 'The organization is about focusing on teaching children/teens/adults across the United States and mostly Mexico the English language. Mostly focusing on children in underserved communities. We focus on volunteering and influence others to help.', 'Our organization focuses on helping and educating children mostly in underserved communities to teach them the English language. We travel to Mexico and other places, also including the United States, to volunteer in many schools, orphanages, homes, etc. We make sure the children we teach feel that we care for them and are there for them whenever they need and not just view us as an "extra class" but as a place where they feel comfortable and distract themselves for a while. We value humility, respect, compassion and commitment on helping others.', 'aprendiendojuntos.or@gmail.com', null, 'https://www.instagram.com/aprendiendojuntos.us/', 'https://highlanderlink.ucr.edu/organization/aprendiendojuntos'),
(139350, 'Archery Club at UCR', 'Registered Student Organization', array['Recreational']::text[], 'Fridays 1:45PM-5:45PM', 'Weekly', 'Archery Club at UCR is an organization that aims to bring the unique aspects of archery to UCR by introducing students new to the sport and by training and exchanging insight with UCR students who have prior experience. As one of the only UC campuses without an archery team, our current main focus is on archery development for people new to the sport. We are also training those with prior experience in preparation for assembling a competitive team to compete in national and intercollegiate events in the future.
Practice Location: Glen Mor Fields
Practice Times: Fridays 1:45pm- 5:45pm
Members!!! If you can come early, please come 10-15 minutes before the start of the practice and help us set up the field.', 'Archery Club at UCR is an organization that aims to allow students with an interest in archery to learn the sport, to hone their skills, and to enter into local and national competitive events as a collegiate archer.', 'If you have inquiries about the club, please email archery.ucr@gmail.com
Archery, unlike most other sports, requires you to outperform your opponent by being in and maintaining your most calm and steady state. A collegiate archer is expected to maintain this mental and physical discipline on the field and in the classroom.
Archery Club at UCR is an organization that aims to bring the unique aspects of archery to UCR by introducing students new to the sport and by training and exchanging insight with UCR students who have prior experience. As one of the only UC campuses without an archery team, our current main focus is on archery development for people new to the sport. We are also training those with prior experience in preparation for assembling a competitive team to compete in national and intercollegiate events in the future.
Practice Location: Glen Mor Fields
Practice Times: Fridays 1:45pm- 5:45pm
Members!!! If you can come early, please come 10-15 minutes before the start of the practice and help us set up the field.', 'archery.ucr@gmail.com', 'https://archery.ucrhighlanders.org/', 'https://www.instagram.com/archeryatucr/', 'https://highlanderlink.ucr.edu/organization/acucr'),
(70937, 'Armenian Student Association', 'Registered Student Organization', array['Cultural']::text[], 'Thursdays at 8:00 pm.', 'Every two weeks', null, 'To advance the Armenian culture, heritage, and history through enriching activities arranged by the organization.', 'To advance the Armenian culture, heritage, and history through enriching activities arranged by the organization.', 'zmanu002@ucr.edu', null, 'http://www.instagram.com/ucr_asa', 'https://highlanderlink.ucr.edu/organization/armenian'),
(368935, 'Art Factory at UCR', 'Registered Student Organization', array['Arts and Expression']::text[], 'Wednesdays, 4-6pm, generally somewhere @HUB!', '1st and 3rd week of each month! Check out our instagram for more specific dates and times!', 'Welcome to Art Factory at UCR! Our club''s objective is to create a fun, inclusive, creative community on campus. We conduct a series of FREE artistic events throughout the quarter for students to come and enjoy. Please fill out our membership form, and after attending 2 meetings, you can join our Highlander link as an official member!
https://docs.google.com/forms/d/e/1FAIpQLSdGg6v_QL0OxA7koz_dzy3n7MJSqvJsxhOa3Mk23shyCCd2ng/viewform?usp=sharing&ouid=109823290533721297721', 'A safe place and creative place for artists in which they can take advantage of a set studio time to create multimedia art. We strive to give students the opportunity to connect with their artistic selves and disconnect from academic pressures.', 'Welcome to Art Factory at UCR! Our club''s objective is to create a fun, inclusive, creative community on campus. We conduct a series of FREE artistic events throughout the quarter for students to come and enjoy. Please fill out our membership form, and after attending 2 meetings, you can join our Highlander link as an official member!
https://docs.google.com/forms/d/e/1FAIpQLSdGg6v_QL0OxA7koz_dzy3n7MJSqvJsxhOa3Mk23shyCCd2ng/viewform?usp=sharing&ouid=109823290533721297721', 'ucrartfactory@gmail.com', 'https://linktr.ee/Ucr.artfactory', 'https://www.instagram.com/artfactory.ucr/', 'https://highlanderlink.ucr.edu/organization/artfactoryucr'),
(71180, 'Art History Graduate Student Association', 'Graduate Student Association', array['Mini-GSA']::text[], 'various', 'Monthly', 'The purpose of this organization shall be to exist as a social and research forum meant to promote collaboration create a sense of community among students and serve as a vital link between faculty and students. AHGSA hosts events through out the year such as: an annual Graduate Student Symposium, gallery trips, guest speakers and association meetings. Additionally, a student representative attends faculty meetings and represents student interests. Through meetings, activities and a focus on departmental development, we aim to support the goals of students within the Art History Department.', 'Graduate Student Organization open to all graduate students in the History of Art Department at the University of California, Riverside', 'The purpose of this organization shall be to exist as a social and research forum meant to promote collaboration create a sense of community among students and serve as a vital link between faculty and students. AHGSA hosts events through out the year such as: an annual Graduate Student Symposium, gallery trips, guest speakers and association meetings. Additionally, a student representative attends faculty meetings and represents student interests. Through meetings, activities and a focus on departmental development, we aim to support the goals of students within the Art History Department.', 'AHGSA.UCR@Gmail.com', null, 'https://www.instagram.com/arthistgrads.ucr/', 'https://highlanderlink.ucr.edu/organization/ahgsa'),
(70903, 'Art History Undergraduate Association', 'Registered Student Organization', array['Academic/Professional']::text[], 'Weekly, Tuesdays, around 6:00PM', 'Weekly', 'The purpose of this organization shall be to exist as a social and research forum meant to promote collaboration, community and serve as a vital link between faculty and students. The club hosts events throughout the year such as: gallery trips, guest speakers and activity. Through meetings and activities, we aim to support the goals of students with an interest in art history.', 'The purpose of the Art History Undergraduate Association is to enhance involvement in the field of Art History among interested UCR students through meetings, lectures, field trips, films, and other events with an art historical focus.', 'The purpose of this organization shall be to exist as a social and research forum meant to promote collaboration, community and serve as a vital link between faculty and students. The club hosts events throughout the year such as: gallery trips, guest speakers and activity. Through meetings and activities, we aim to support the goals of students with an interest in art history.', 'ahua.ucr@gmail.com', 'https://arthistory.ucr.edu/undergraduate/art-history-association/', 'https://www.instagram.com/ucr_ahua/', 'https://highlanderlink.ucr.edu/organization/ahua'),
(382273, 'Artificial Intelligence Student Collective', 'Registered Student Organization', array['Academic/Professional']::text[], null, 'Weekly', null, 'The AI Student Collective is a national network of student organizations dedicated to providing accessible AI literacy through pre-professional programs and events.', 'The AI Student Collective is a national network of student organizations dedicated to providing accessible AI literacy through pre-professional programs and events. Powered by the Humans for AI nonprofit, we focus on elevating the student experience by providing professional development opportunities, from creating education initiatives to orchestrating industry readiness.', null, null, 'https://www.instagram.com/aisc_riv/', 'https://highlanderlink.ucr.edu/organization/humansforai'),
(401407, 'AscendUCR', 'Registered Student Organization', array['Academic/Professional']::text[], 'Make Sure to Check Out Our Instagram for Event Schedule', 'Weekly', null, 'Ascend is the largest global network advancing Pan-Asian professionals in the workplace. It’s our mission to build community and ignite change by developing, elevating, and empowering the API leaders of tomorrow.', 'AscendUCR is the official student chapter of the overlaying organization Ascend. Ascend is the largest nonprofit organization filled with a global network advancing Pan-Asian professionals in the workplace. It’s our mission to build community and ignite change by developing, elevating, and empowering the API leaders of tomorrow.
🔸Connect. Inspire. Ascend.
🔸🔸Pan-Asian Leadership Org for Professional Networking
🙌 Open to ALL majors/cultural backgrounds', 'ascenducr@gmail.com', 'https://linktr.ee/AscendUCR?utm_source=linktree_profile_share&ltsid=724b9d84-e851-4f49-b723-1c93b9cbd439', 'https://www.instagram.com/ascend_ucr/', 'https://highlanderlink.ucr.edu/organization/ascenducr'),
(70917, 'Asian American Christian Fellowship', 'Registered Student Organization', array['Spiritual/Religious/Atheist']::text[], 'Large Groups are on Wednesday @ Hub 302 North from 8:00PM - 10:00PM', 'Weekly', '-
Our Large Groups are typically held on Wednesdays at HUB 302 North from 8:00-10:00 pm. We''d love to see you!
Feel free to join our Facebook group for updates too: https://www.facebook.com/groups/31096998519914050/', 'The mission of AACF is to reach into the university and collegiate community, primarily to those who are Asian Pacific Americans, with the life-changing message of Jesus Christ and fellowship with other believers.', 'The mission of AACF is to reach into the university and collegiate community, primarily to those who are Asian Pacific Americans (but you don''t have to be), with the life-changing message of Jesus Christ and fellowship with other believers.
-
Our Large Groups are typically held on Wednesdays at HUB 302 North from 8:00-10:00 pm. We''d love to see you!
Feel free to join our Facebook group for updates too: https://www.facebook.com/groups/31096998519914050/', 'aacf.ucr@aacf.org', 'https://aacfucriverside.wixsite.com/home', 'https://www.instagram.com/aacfucriverside/', 'https://highlanderlink.ucr.edu/organization/aacf'),
(100509, 'Asian Americans of Riverside Theatre', 'Registered Student Organization', array['Arts and Expression']::text[], 'Although we don''t have consistent meetings, when we''re in production, we hold rehearsals typically at night, around 6PM - 11PM, Monday-Thursday.', 'We do not typically hold general meetings, you can get involved with us by auditioning for cast or crew and attending our performances!', null, 'Celebrating diverse voices through theater and film. Welcome to AART!', 'Asian Americans of Riverside Theatre provides a space for unrecognized and under-appreciated groups in mainstream media, with an emphasis on Asian-American voices, to tell stories through theatrical and film arts.
We strive to welcome all artists and storytellers of all backgrounds to share their creativity and vision, no matter the level of experience or background.
Our organization focuses on giving students the opportunity to collaborate on creating theatrical and filmed performances while also traveling as a community to view and appreciate the performing arts.
We run workshops, put on productions, and hold talkbacks with artists currently working in the industry.
As a student-led non-profit, we accept donations through our GoFundMe to help our organization''s efforts to keep the show running! No funds are put to any independent or personal gains; all funds go toward funding production aspects, including (but not limited to) costumes, props, and licensing, as well as nurturing a healthy environment for our community through field trips in consuming and analyzing artistry.', 'aart.ucr@gmail.com', 'https://linktr.ee/ucr.aart?utm_source=linktree_profile_share&ltsid=600b6eef-c716-4d6c-960f-e713bd7e7d8a', 'https://www.instagram.com/aart.ucr?utm_source=ig_web_button_share_sheet&igsh=ZDNlZDc0MzIxNw==', 'https://highlanderlink.ucr.edu/organization/aart'),
(430444, 'Asian Pacific Empowerment Collective at UCR', 'Registered Student Organization', array['Cultural']::text[], null, 'All meeting dates/times are posted on our Instagram @apecucr!', null, 'We aim to empower Asian Pacific communities by creating spaces to learn about present and historical issues in the context of our peoples and working as a collective to create a safe, informed, and welcoming space.', 'What is Asian Pacific Empowerment Collective?
We''re an organization of UCR students targeted towards empowering Asian Pacific communities, creating spaces to learn about present and historical issues in the context of our peoples, and working as a collective to create a
safe, informed, and welcoming space.
Our main points of unity are:
Creating safe, informed community
Learning our histories to write our futures
AAPI empowerment, leadership, and advocacy
SOLIDARITY ALWAYS
So long as you share an interest in and commitment to these four points of unity, all UCR faculty, students, and community members are welcome!', 'apecucr@gmail.com', null, null, 'https://highlanderlink.ucr.edu/organization/apecucr'),
(76530, 'Asian Pacific Islander Student Advisory Council', 'Department Affiliated Organization', array['Cultural']::text[], null, 'Weekly', 'Asian Pacific Islander Student Advisory Council (APISAC) is a collaborative group of Asian Pacific Islander student organizations that work together to build unity in our community at UCR. We plan various events and meet to discuss issues in our orgs.', 'Asian Pacific Islander Student Advisory Council (APISAC) is a collaborative group of Asian Pacific Islander student organizations that work together to build unity in our community at UCR. We plan various events and meet to discuss issues in our orgs.', 'Asian Pacific Islander Student Advisory Council (APISAC) is a collaborative group of Asian Pacific Islander student organizations that work together to build unity in our community at UCR. We plan various events and meet to discuss issues in our orgs.', 'atsai043@ucr.edu', null, 'http://www.instagram.com/ucr.apisac', 'https://highlanderlink.ucr.edu/organization/apisac'),
(414839, 'Aspire, Xplore, Ignite, and Succeed.', 'Registered Student Organization', array['Academic/Professional']::text[], null, 'Monthly', null, 'The purpose of this organization shall be to empower students from every background and culture in UC Riverside to help students achieve success by aligning with like-minded individuals, resources, and opportunities.', 'AXIS (Empowering Students to Aspire, Xplore, Ignite, and Succeed) is a multidisciplinary student organization at UC Riverside committed to helping students unlock their full potential. The club provides a supportive community where members connect with peers of similar interests, gain mentorship, and access professional development opportunities across fields such as medicine, law, and computer science. Through workshops, networking events, speaker panels, and hands-on initiatives, AXIS equips students with the skills and connections to excel academically and professionally. With a strong focus on inclusivity, leadership development, and collaboration, AXIS empowers its members to turn ambition into achievement and build a lasting impact within the UCR community and beyond', 'axisatucr@gmail.com', null, null, 'https://highlanderlink.ucr.edu/organization/axisucr'),
(71566, 'Associated Students of UCR', 'Department Affiliated Organization', array['Department Affiliated Organization']::text[], null, null, null, 'The Associated Students of University of California, Riverside (ASUCR) is the official student government at UCR representing over 18,000 undergraduates.', 'Hello Highlander!
Thank you for your interest in ASUCR. In order to be apart of the ASUCR HighlanderLink’s roster, you will need to have a position in ASUCR. This can be achieved by being elected, becoming a First-Year Fellow, or becoming an intern in the office.
The Associated Students of University of California, Riverside (ASUCR) is the official undergraduate student government of UCR.
ASUCR acts as the liaison between students and administrators by providing an outlet for the student body to express concerns, questions, and suggestions about the university.
ASUCR advocates, represents, and educates the student body as official units of the university on three main levels: internally, externally, and financially.
Keep an eye on our HighlanderLink page for news and events, as well as our website, Facebook, Twitter, and Instagram.
If you have any questions, please feel free to contact us!', 'asucrpresident@ucr.edu', 'http://asucrexchange.ucr.edu/', null, 'https://highlanderlink.ucr.edu/organization/asucr'),
(70967, 'Associated Students Program Board', 'Department Affiliated Organization', array['Department Affiliated Organization']::text[], null, 'Weekly', null, 'The office of ASPB is dedicated to programming quality campus entertainment for the undergraduate population at the University of California, Riverside that appeals to the diverse communities and enhances campus life.', 'The office of ASPB is dedicated to programming quality campus entertainment for the undergraduate population at the University of California, Riverside that appeals to the diverse communities and enhances campus life.
The Associated Students Program Board (ASPB) is a student-run programming entity on the UC Riverside campus. Established in 1986, ASPB is funded by quarterly feeds paid by undergraduate students. The board is comprised of 16 full-time undergraduate students who work primarily, though not exclusively, in the following seven divisions: Concerts, Special Events, Films & Lectures, Contemporary Culture, Marketing, Membership, and Leadership. The first four programming divisions plan events (both large and small); all programs are voted on and approved by quorum of the board. The other two divisions provide support essential to the success of the events and the respectively. All 13 directors, the Vice Chairperson and Marketing Chairperson hold votes in program requests proposed by the board.', 'aspb@ucr.edu', 'http://aspb.ucr.edu', null, 'https://highlanderlink.ucr.edu/organization/aspb'),
(70878, 'Association for Computing Machinery (ACM) at UCR', 'Registered Student Organization', array['Academic/Professional']::text[], 'All ACM events can be found on the Instagram page.', 'Weekly', null, 'ACM is UCR''s premier technical organization with a focus on computer science and open to all years, majors, and skill levels.', 'The Association for Computing Machinery (ACM) at the University of California, Riverside (UCR) is a technical organization with a focus on computer science that is open to all years, majors, and skill levels.Our focus includes technical, professional development, community, knowledge growth, leadership, and more. With project-based programs, technical workshops, hackathons, and networking, ACM provides students the tools and experience to further their education and future.
All ACM at UCR links: acmucr.carrd.co', 'contact.acmucr@gmail.com', 'acm.cs.ucr.edu', 'https://www.instagram.com/acm_ucr', 'https://highlanderlink.ucr.edu/organization/acm'),
(333325, 'Association for Information Systems', 'Registered Student Organization', array['Academic/Professional']::text[], 'Tuesdays from 5–6 PM at SSC 123!', 'Weekly', 'The Association for Information Systems (AIS) at UCR is dedicated to enhancing the technical and professional skills of students of all majors interested in information systems, data analysis, and other related fields with weekly meetings and workshops.
The Association for Information Systems (AIS) at the University of California, Riverside is a student-run organization that aims to develop and promote professional and technical skills that are valuable to members interested in information systems, data analysis, and other related fields. Our vision is to spread the importance and impact of information systems to all majors. With weekly meetings, we welcome all majors with opportunities and workshops for networking, relevant certifications, and professional and personal development, and exposure among working professionals, guest speakers, and peers.
Check out our Instagram (@aisatucr) for information about our weekly meetings.
All of our information can be found here!', 'The Association for Information Systems (AIS) at UCR is dedicated to enhancing the technical and professional skills of students of all majors interested in information systems, data analysis, and other related fields with weekly meetings and workshops.', 'The Association for Information Systems (AIS) at UCR is dedicated to enhancing the technical and professional skills of students of all majors interested in information systems, data analysis, and other related fields with weekly meetings and workshops.
The Association for Information Systems (AIS) at the University of California, Riverside is a student-run organization that aims to develop and promote professional and technical skills that are valuable to members interested in information systems, data analysis, and other related fields. Our vision is to spread the importance and impact of information systems to all majors. With weekly meetings, we welcome all majors with opportunities and workshops for networking, relevant certifications, and professional and personal development, and exposure among working professionals, guest speakers, and peers.
Check out our Instagram (@aisatucr) for information about our weekly meetings.
All of our information can be found here!', 'aisatucr@gmail.com', 'https://aisnet.org/', 'https://www.instagram.com/aisatucr/', 'https://highlanderlink.ucr.edu/organization/ais'),
(420837, 'Association for Women in Mathematics Chapter at UCR', 'Department Affiliated Organization', null, null, 'Monthly', null, 'The Association for Women in Mathematics (AWM) at UCR fosters a supportive and inclusive community, promoting equity, professional growth, and engagement for women and underrepresented genders in mathematics at UC Riverside.', null, null, null, null, 'https://highlanderlink.ucr.edu/organization/ucrawm'),
(414863, 'Association of Environmental Professionals at UCR', 'Registered Student Organization', array['Academic/Professional']::text[], null, 'Every two weeks', null, 'The AEP Student Chapter at UCR connects students with environmental professionals to foster mutual growth. We support future environmental leaders through networking, mentorship, and events that build knowledge, skills, and career readiness.', 'The Association of Environmental Professionals (AEP) Student Chapter at UCR is dedicated to building strong connections between students and environmental professionals, fostering mutual growth and collaboration. Our mission is to support students preparing for careers in the environmental field by providing opportunities to learn from experts, explore diverse environmental professions, and develop valuable professional networks. Through events, mentorship, and community engagement, AEP empowers students to expand their knowledge, gain real-world insights, and take meaningful steps toward impactful environmental careers.', null, null, null, 'https://highlanderlink.ucr.edu/organization/aepucr'),
(70848, 'Association of Latino Professionals For America', 'Registered Student Organization', array['Academic/Professional']::text[], 'Tuesdays/Thursdays 6 PM', 'Weekly', 'At the chapter level, our mission is to equip members with the skills and confidence needed to succeed in their careers. We provide guidance on key areas such as resume and cover letter development, interview preparation, networking strategies, LinkedIn optimization, and business etiquette.
We host professionals from a diverse range of industries and companies at our weekly meetings, where they share their experiences and insights in a more personal, interactive setting.', 'ALPFA is a nationally recognized organization dedicated to empowering and developing Latino leaders across all industries. We provide professional development, high-impact networking, and direct access to top-tier companies.', 'Who We Are
The Association of Latino Professionals For America (ALPFA) is a nationally recognized organization dedicated to empowering and developing leaders across every sector of the economy. Our national presence enables us to build strong partnerships with Fortune 500 companies and Big 4 firms, creating direct pathways for our members to access top-tier opportunities and networks. While rooted in the Latino community, ALPFA is open to students of all majors and backgrounds who are committed to personal and professional growth.
At the chapter level, our mission is to equip members with the skills and confidence needed to succeed in their careers. We provide guidance on key areas such as resume and cover letter development, interview preparation, networking strategies, LinkedIn optimization, and business etiquette.
We host professionals from a diverse range of industries and companies at our weekly meetings, where they share their experiences and insights in a more personal, interactive setting.', 'ucralpfa@gmail.com', 'https://linktr.ee/ucralpfa', null, 'https://highlanderlink.ucr.edu/organization/ucralpfa'),
(431042, 'Association of Muslims in Politics and Law', 'Registered Student Organization', array['Academic/Professional']::text[], null, 'Monthly', null, 'AMPL at UCR empowers Muslim students pursuing careers in law, public policy, and governance through mentorship, professional development, academics, and advocacy — building a supportive community rooted in faith and shaping future Muslim leaders.', 'Association of Muslims in Politics and Law (AMPL) at UCR is a student organization dedicated to guiding and empowering Muslim students interested in pursuing careers in law, public policy, and related fields. Recognizing a gap in professional development opportunities for the Muslim community, AMPL provides a platform for education, mentorship, and advocacy in the political and legal spheres.
AMPL fosters a supportive and inclusive community that provides resources and mentorship while amplifying the voices of Muslims within the broader community. Our programming is built around three core pillars: Professional Development (resume and LinkedIn workshops, mentorship with Muslim law students, networking events), Academics (LSAT/GSAT preparation, mock trials, tutoring), and Advocacy (support for Muslim student organizations, petition and legislation writing, and highlighting Muslim leaders in politics and law). Through educational initiatives, networking opportunities, and collaborative work, AMPL equips its members with the support necessary to navigate and excel in their chosen professions while remaining rooted in their faith.
Our vision is to cultivate a generation of empowered Muslim leaders who actively shape the future of politics, law, and public policy, making meaningful contributions to society.', 'amplucr@gmail.com', null, null, 'https://highlanderlink.ucr.edu/organization/amplucr'),
(136319, 'Astronomy Club @ UCR', 'Registered Student Organization', array['Academic/Professional']::text[], 'Wednesdays at 5:00 PM', 'Monthly', null, 'The purpose of this organization shall be to bring together those throughout UCR and the general public that share a same level of appreciation of the space-related sciences to facilitate a diverse supportive environment.', 'The Astronomy Club @ UCR strives to promote knowledge and passion of the space-related sciences through our outreach and engagement of all members of UCR and the general public. We intend to bring together those curious about astronomy and share our excitement and wonder with each other and the community.
Join our discord with SPS!
https://discord.gg/mcSc4WGa
Follow us on Instagram!
@astroclubtucr', 'astroclubatucr@gmail.com', 'https://sites.google.com/view/astronomyclubatucr/', 'https://www.instagram.com/astroclubatucr/', 'https://highlanderlink.ucr.edu/organization/astroclubucr'),
(404658, 'Astronomy Union for Reading, Outreach and Research Activities', 'Graduate Student Association', array['Mini-GSA']::text[], 'Updated quarterly. Check our website or social media for updated info', 'Every two weeks', null, 'Promote research culture through journal clubs, talks, workshops, and outreach. Foster meaningful discussions among graduate students, postdocs, and motivated undergraduates to inspire collaboration and innovation in research.', 'AURORA (Astronomy Union for Reading, Outreach, and Research Activities) aims to build a vibrant community for fostering collaboration, learning, and innovation in astronomy. Through journal clubs, workshops, outreach, and engaging discussions, we connect students and researchers passionate about the cosmos.', 'aurora.ucr@gmail.com', null, 'https://www.instagram.com/ucr.aurora/', 'https://highlanderlink.ucr.edu/organization/aurora'),
(340765, 'Audeamus', 'Department Affiliated Organization', null, 'Wednesday', 'Weekly', null, 'Audeamus was started in 2007 at UC Riverside as a multidisciplinary honors journal for undergraduate students across the University of California (UC) system.', 'Audeamus was started in 2007 at UC Riverside as a multidisciplinary honors journal for undergraduate students across the University of California (UC) system. Based at University Honors (UH) in UC Riverside, the journal started with the belief that students should be able to showcase any work that was of the highest merit, no matter what it was. There were many academic journals and literary magazines out there, but not as many places where anything could be published.
From 2007 to 2015, Audeamus was an annual journal put together by UCR University Honors students, but containing the work of undergraduate students across the nine University of California schools. In 2016, Audeamus published its 10th edition and decided that with its 11th edition, it would become a national journal to be able to accept submissions from beyond just the UC system.
The Audeamus journal publishes works of all mediums – from research papers to artwork and photography to musical scores – basically anything reproducible on paper. Audeamus is produced by UCR University Honors students of all disciplines and majors; the students do everything from research and advertisement, to journal design and submissions. Flipping through the pages of any issue, you can find an organic chemistry research paper right next to a literary analysis, and just down the table of contents, you might find some photography or a biology paper.
The world is a fairly eclectic place, so why not our journal? That’s what our name means in Latin: Let us dare. Let us dare to publish a journal that is as varied as the world is.', 'ucraudeamus@gmail.com', 'https://audeamus.wixsite.com/ucjournal', 'https://www.instagram.com/audeamus_journal/', 'https://highlanderlink.ucr.edu/organization/audeamus'),
(380945, 'Avant-Garde A Cappella Group', 'Registered Student Organization', array['Arts and Expression']::text[], 'Every Thursday, 5-7 PM', 'Weekly', 'Avant-Garde Acapella is here to foster a community of driven singers by providing performance opportunities and regular meetings to practice music and interact with fellow Highlanders to bond over a shared love of music. Our goal is to provide a safe-space for people to express their passion for music and singing while also bringing more attention to the arts and music scene here at UCR.', 'The purpose(s) of this organization shall be to foster a community of driven singers, providing performance opportunities, and experimenting with various musical styles. We aim to bring more attention to the arts and music scene of Riverside.', 'Avant-Garde Acapella is here to foster a community of driven singers by providing performance opportunities and regular meetings to practice music and interact with fellow Highlanders to bond over a shared love of music. Our goal is to provide a safe-space for people to express their passion for music and singing while also bringing more attention to the arts and music scene here at UCR.', 'avantgardeacapella@gmail.com', null, 'https://www.instagram.com/avantgarde_acapella/', 'https://highlanderlink.ucr.edu/organization/avant-garde'),
(425057, 'Aviation Club at UC Riverside', 'Registered Student Organization', array['Academic/Professional']::text[], 'Generally, every other Wednesday 7-9PM.', 'Weekly', null, 'The purpose of this organization shall be to cultivate a passion for flying at UCR. Connect with other students who share a passion for aviation, find mentors who can provide guidance and support, and build lasting friendships with fellow aviators.', null, null, null, 'https://www.instagram.com/ucraviationclub?igsh=MzRlODBiNWFlZA==', 'https://highlanderlink.ucr.edu/organization/aviationclub'),
(70975, 'Badminton Club at UCR', 'Registered Student Organization', array['Recreational']::text[], 'Tuesday/Thursday around 7:30PM to 9:30PM', 'Weekly', 'This club is for anyone who likes to play badminton or is interested in learning the sport.
