(70968, 'Highlander Band at UCR', 'Department Affiliated Organization', array['Department Affiliated Organization']::text[], null, 'Twice a week', null, 'We are the Highlander Band at UCR. Our goal is to provide a quality student band for all members of the university. We attempt to support the school spirit by performing at men''s and women''s basketball games as well as other various school functions.', 'Welcome! We are the Highlander Pep Band. Have any experience playing an instrument? Great! Come check us out and play along side with us at all the games. We''re always welcoming new comers!', 'riversidehighlanderband@gmail.com', 'http://studentlife.ucr.edu/UCRTRADITIONS/Pages/highlanderBand.aspx', null, 'https://highlanderlink.ucr.edu/organization/highlanderband'),
(347274, 'Highlander Business Society', 'Registered Student Organization', array['Academic/Professional']::text[], '8pm on Tuesdays', 'Weekly', null, 'Highlander Business Society (HBS) is a professional student organization, established on 4 core values to prepare our members for the professional world: Professionalism, Leadership, Community, and Growth.', 'Highlander Business Society (HBS) is a professional student organization, established on 4 core values to prepare our members for the professional world: Professionalism, Leadership, Community, and Mentorship. HBS was founded in October 2021. We are open to undergraduate students and all majors. Our goal is to foster a thriving community of business professionals at UCR.
Keep up to date with our events on our Instagram: @hbsucr https://www.instagram.com/hbsucr/', 'hbsucr@gmail.com', 'https://hbsucr.weebly.com/', 'https://www.instagram.com/hbsucr/', 'https://highlanderlink.ucr.edu/organization/highlanderbusinesssociety'),
